begin;
create table public.community_challenges(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,group_id uuid not null references public.community_groups(id) on delete cascade,title text not null check(char_length(title) between 1 and 80),start_day date not null,end_day date not null,timezone text not null,goal_days integer not null check(goal_days between 1 and 42),canceled_at timestamptz,created_at timestamptz not null default now(),check(end_day>=start_day and end_day-start_day<42));
create index community_challenges_user on public.community_challenges(user_id,id);
create index community_challenges_group on public.community_challenges(group_id,id);
create table public.community_challenge_members(user_id uuid not null references auth.users(id) on delete cascade,challenge_id uuid not null references public.community_challenges(id) on delete cascade,generation integer not null,joined_at timestamptz not null default now(),primary key(user_id,challenge_id));
create table public.community_challenge_contributions(user_id uuid not null references auth.users(id) on delete cascade,challenge_id uuid not null references public.community_challenges(id) on delete cascade,day date not null,kind text not null check(kind in('workout','rest')),source_workout_id uuid references public.workouts(id) on delete cascade,source_updated_at timestamptz,created_at timestamptz not null default now(),primary key(user_id,challenge_id,day),unique(user_id,challenge_id,source_workout_id),check((kind='workout' and source_workout_id is not null and source_updated_at is not null)or(kind='rest' and source_workout_id is null and source_updated_at is null)));
do $$declare t text;begin foreach t in array array['community_challenges','community_challenge_members','community_challenge_contributions']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
create function public.community_challenge_access(p_id uuid,p_user uuid) returns boolean language sql volatile security definer set search_path='' as $$select exists(select 1 from public.community_challenges c where c.id=p_id and public.community_feature_enabled('challenges',p_user) and public.community_feature_enabled('groups',p_user) and public.community_group_member(c.group_id,p_user) and public.community_active(c.user_id) and public.community_group_member(c.group_id,c.user_id) and exists(select 1 from public.community_group_members gm where gm.group_id=c.group_id and gm.user_id=p_user and gm.joined_at<=c.created_at) and not exists(select 1 from public.community_blocks where(blocker_user_id=p_user and blocked_user_id=c.user_id)or(blocker_user_id=c.user_id and blocked_user_id=p_user)))$$;
create function public.community_challenge_participant(p_id uuid,p_user uuid) returns boolean language sql volatile security definer set search_path='' as $$select public.community_challenge_access(p_id,p_user) and exists(select 1 from public.community_challenge_members m join public.community_profiles p using(user_id) where m.challenge_id=p_id and m.user_id=p_user and m.generation=p.generation and m.joined_at >= (select joined_at from public.community_group_members where group_id=(select group_id from public.community_challenges where id=p_id) and user_id=p_user))$$;
create function public.community_challenge_artifact_valid(a public.community_challenge_contributions) returns boolean language sql volatile security definer set search_path='' as $$select case when a.kind='rest' then true else exists(select 1 from public.workouts w join public.community_challenges c on c.id=a.challenge_id where w.id=a.source_workout_id and w.user_id=a.user_id and w.updated_at=a.source_updated_at and w.completed_at is not null and(w.completed_at at time zone c.timezone)::date=a.day)end$$;
create function public.community_challenge_dto(p_id uuid,p_privacy boolean default false) returns jsonb language plpgsql volatile security definer set search_path='' as $$declare c public.community_challenges;mine jsonb;participants integer;team integer;mycount integer;can_see_team boolean;begin
 select * into c from public.community_challenges where id=p_id;
 can_see_team:=not p_privacy and public.community_challenge_access(p_id,auth.uid());
 select coalesce(jsonb_agg(jsonb_build_object('day',a.day,'kind',a.kind,'valid',public.community_challenge_artifact_valid(a)) order by a.day),'[]') into mine from public.community_challenge_contributions a where a.challenge_id=p_id and a.user_id=auth.uid();
 select count(*) filter(where public.community_challenge_artifact_valid(a)) into mycount from public.community_challenge_contributions a where a.challenge_id=p_id and a.user_id=auth.uid();
 select count(*) into participants from public.community_challenge_members m where can_see_team and m.challenge_id=p_id and public.community_challenge_participant(p_id,m.user_id) and not exists(select 1 from public.community_blocks where(blocker_user_id=auth.uid() and blocked_user_id=m.user_id)or(blocker_user_id=m.user_id and blocked_user_id=auth.uid()));
 select count(*) filter(where public.community_challenge_artifact_valid(a)) into team from public.community_challenge_contributions a where can_see_team and a.challenge_id=p_id and public.community_challenge_participant(p_id,a.user_id) and not exists(select 1 from public.community_blocks where(blocker_user_id=auth.uid() and blocked_user_id=a.user_id)or(blocker_user_id=a.user_id and blocked_user_id=auth.uid()));
 return jsonb_build_object('id',c.id,'groupId',c.group_id,'title',case when c.user_id=auth.uid() or (not p_privacy and public.community_challenge_access(c.id,auth.uid())) then c.title else 'Challenge you joined' end,'startDay',c.start_day,'endDay',c.end_day,'timezone',c.timezone,'goalDays',c.goal_days,'joined',public.community_challenge_participant(p_id,auth.uid()),'isOwner',c.user_id=auth.uid(),'canceled',c.canceled_at is not null,'myProgress',case when jsonb_array_length(mine)>0 then mycount end,'teamProgress',case when can_see_team and exists(select 1 from public.community_challenge_contributions a where a.challenge_id=p_id and public.community_challenge_participant(p_id,a.user_id) and not exists(select 1 from public.community_blocks where(blocker_user_id=auth.uid() and blocked_user_id=a.user_id)or(blocker_user_id=a.user_id and blocked_user_id=auth.uid()))) then team end,'participants',participants,'days',mine);
end $$;
create function public.community_challenges_rpc(p_operation text,p_args jsonb default '{}') returns table(result jsonb) language plpgsql volatile security definer set search_path='' as $$declare u uuid:=auth.uid();cid uuid;gid uuid;c public.community_challenges;d date;tz text;startdate date;enddate date;w public.workouts;gen integer;begin
 perform public.community_lock();if u is null then raise exception 'community_access_denied';end if;cid:=(p_args->>'id')::uuid;
 if p_operation='leave' then delete from public.community_challenge_contributions where user_id=u and challenge_id=cid;delete from public.community_challenge_members where user_id=u and challenge_id=cid;return query select jsonb_build_object('done',true);return;
 elsif p_operation='removeContribution' then delete from public.community_challenge_contributions where user_id=u and challenge_id=cid and day=(p_args->>'day')::date;return query select jsonb_build_object('done',true);return;
 elsif p_operation='cancel' then update public.community_challenges set canceled_at=coalesce(canceled_at,now()) where id=cid and user_id=u;if not found then raise exception 'community_unavailable';end if;return query select jsonb_build_object('done',true);return;end if;
 if p_operation='getMine' and exists(select 1 from public.community_challenges where id=cid and (user_id=u or exists(select 1 from public.community_challenge_members cm where cm.challenge_id=cid and cm.user_id=u))) then return query select jsonb_build_object('challenge',public.community_challenge_dto(cid,true));return;end if;
 if p_operation='get' and exists(select 1 from public.community_challenges where id=cid and user_id=u) then return query select jsonb_build_object('challenge',public.community_challenge_dto(cid));return;end if;
 if p_operation='listMine' then return query select jsonb_build_object('challenges',coalesce(jsonb_agg(public.community_challenge_dto(id,true) order by id),'[]'),'nextCursor',case when count(*)=20 then max(id::text) end) from(select id from public.community_challenges where (user_id=u or exists(select 1 from public.community_challenge_members cm where cm.challenge_id=community_challenges.id and cm.user_id=u)) and (p_args->>'after' is null or id>(p_args->>'after')::uuid) order by id limit 20) own_page;return;end if;
 if not public.community_feature_enabled('challenges',u) or not public.community_feature_enabled('groups',u) then raise exception 'community_unavailable';end if;
 if p_operation='create' then
 gid:=(p_args->>'groupId')::uuid;tz:=p_args->>'timezone';startdate:=(p_args->>'startDay')::date;enddate:=(p_args->>'endDay')::date;
 if not public.community_group_member(gid,u) or not exists(select 1 from pg_timezone_names where name=tz) then raise exception 'community_unavailable';end if;
 if (p_args->>'confirmed')::boolean is distinct from true or startdate<(now() at time zone tz)::date or startdate>(now() at time zone tz)::date+7 or enddate<startdate or enddate-startdate>=42 or (p_args->>'goalDays')::integer not between 1 and enddate-startdate+1 or nullif(btrim(p_args->>'title'),'') is null or char_length(p_args->>'title')>80 or not public.community_text_safe(p_args->>'title') or(p_args->>'title')~*'(https?://|www\.|@)' then raise exception 'community_invalid_input';end if;
 select * into c from public.community_challenges where id=cid;
 if found then if c.user_id<>u or c.group_id<>gid or c.title<>btrim(p_args->>'title') or c.start_day<>startdate or c.end_day<>enddate or c.timezone<>tz or c.goal_days<>(p_args->>'goalDays')::integer then raise exception 'community_conflict';end if;
 else if(select count(*) from public.community_challenges where group_id=gid)>=20 then raise exception 'community_rate_limited';end if;insert into public.community_challenges(id,user_id,group_id,title,start_day,end_day,timezone,goal_days) values(cid,u,gid,btrim(p_args->>'title'),startdate,enddate,tz,(p_args->>'goalDays')::integer);end if;
 return query select jsonb_build_object('challenge',public.community_challenge_dto(cid));return;
 elsif p_operation='list' then gid:=(p_args->>'groupId')::uuid;if not public.community_group_member(gid,u) then raise exception 'community_unavailable';end if;
 for c in select * from (select * from public.community_challenges where group_id=gid and public.community_challenge_access(id,u) order by created_at desc,id desc limit 20) delivered where delivered.user_id<>u loop
 begin perform id from public.community_issue_report_receipt('challenge',c.id::text);exception when raise_exception then if sqlerrm<>'community_rate_limited' then raise;end if;end;
 end loop;
 return query select jsonb_build_object('challenges',coalesce(jsonb_agg(public.community_challenge_dto(challenge_row.id) order by challenge_row.created_at desc,challenge_row.id desc),'[]')) from (select * from public.community_challenges where group_id=gid and public.community_challenge_access(id,u) order by created_at desc,id desc limit 20) challenge_row;return;end if;
 if not public.community_challenge_access(cid,u) then raise exception 'community_unavailable';end if;select * into c from public.community_challenges where id=cid;
 if p_operation='get' then
 if c.user_id<>u then begin perform id from public.community_issue_report_receipt('challenge',c.id::text);exception when raise_exception then if sqlerrm<>'community_rate_limited' then raise;end if;end;end if;
 return query select jsonb_build_object('challenge',public.community_challenge_dto(cid));return;end if;
 if c.canceled_at is not null or(now() at time zone c.timezone)::date>c.end_day then raise exception 'community_unavailable';end if;
 if p_operation='join' then
 if(p_args->>'confirmed')::boolean is distinct from true then raise exception 'community_invalid_input';end if;select generation into gen from public.community_profiles where user_id=u;if not public.community_challenge_participant(cid,u) then delete from public.community_challenge_contributions where user_id=u and challenge_id=cid;insert into public.community_challenge_members(user_id,challenge_id,generation) values(u,cid,gen) on conflict(user_id,challenge_id) do update set generation=excluded.generation,joined_at=now();end if;
 elsif p_operation='contribute' then
 if not public.community_challenge_participant(cid,u) or(p_args->>'confirmed')::boolean is distinct from true then raise exception 'community_unavailable';end if;d:=(p_args->>'day')::date;
 if d<c.start_day or d>c.end_day or d>(now() at time zone c.timezone)::date or d<(now() at time zone c.timezone)::date-7 or d<(select(joined_at at time zone c.timezone)::date from public.community_challenge_members where user_id=u and challenge_id=cid) then raise exception 'community_invalid_input';end if;
 if p_args->>'kind'='workout' then select * into w from public.workouts where id=(p_args->>'sourceWorkoutId')::uuid and user_id=u and completed_at is not null and(completed_at at time zone c.timezone)::date=d and completed_at>=(select joined_at from public.community_challenge_members where user_id=u and challenge_id=cid);if not found then raise exception 'community_unavailable';end if;
 elsif p_args->>'kind'<>'rest' or p_args ? 'sourceWorkoutId' then raise exception 'community_invalid_input';end if;
 insert into public.community_challenge_contributions(user_id,challenge_id,day,kind,source_workout_id,source_updated_at) values(u,cid,d,p_args->>'kind',w.id,w.updated_at) on conflict(user_id,challenge_id,day) do update set kind=excluded.kind,source_workout_id=excluded.source_workout_id,source_updated_at=excluded.source_updated_at;
 else raise exception 'community_invalid_input';end if;
 if c.user_id<>u then begin perform id from public.community_issue_report_receipt('challenge',c.id::text);exception when raise_exception then if sqlerrm<>'community_rate_limited' then raise;end if;end;end if;
 return query select jsonb_build_object('challenge',public.community_challenge_dto(cid));end $$;
create function public.community_challenge_withdraw() returns trigger language plpgsql security definer set search_path='' as $$begin if old.status='active' and new.status<>'active' then delete from public.community_challenge_contributions where user_id=new.user_id;delete from public.community_challenge_members where user_id=new.user_id;update public.community_challenges set canceled_at=coalesce(canceled_at,now()) where user_id=new.user_id;end if;return new;end $$;
create function public.community_challenge_group_departure() returns trigger language plpgsql security definer set search_path='' as $$begin
 if old.state='member' and (TG_OP='DELETE' or new.state<>'member' or new.generation is distinct from old.generation or new.joined_at is distinct from old.joined_at) then
 delete from public.community_challenge_contributions where user_id=old.user_id and challenge_id in(select id from public.community_challenges where group_id=old.group_id);
 delete from public.community_challenge_members where user_id=old.user_id and challenge_id in(select id from public.community_challenges where group_id=old.group_id);
 update public.community_challenges set canceled_at=coalesce(canceled_at,now()) where user_id=old.user_id and group_id=old.group_id;
 end if;if TG_OP='DELETE' then return old;else return new;end if;end $$;
create trigger community_challenge_group_departure after update or delete on public.community_group_members for each row execute function public.community_challenge_group_departure();
create trigger community_challenge_withdraw after update of status on public.community_profiles for each row execute function public.community_challenge_withdraw();
alter function public.community_export_page(text,text,integer) rename to community_export_page_before_challenges;
create function public.community_export_page(p_category text,p_after text default null,p_limit integer default 500) returns table(item_key text,item jsonb) language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or p_limit is null or p_limit not between 1 and 500 then raise exception 'community_access_denied';end if;
 if p_category='challenges' then return query select id::text,jsonb_build_object('id',id,'groupId',group_id,'title',title,'startDay',start_day,'endDay',end_day,'timezone',timezone,'goalDays',goal_days,'canceledAt',canceled_at) from public.community_challenges where user_id=auth.uid() and(p_after is null or id::text>p_after) order by id::text limit p_limit;
 elsif p_category='challengeContributions' then return query select challenge_id::text||':'||day::text,jsonb_build_object('challengeId',challenge_id,'day',day,'kind',kind,'sourceWorkoutId',source_workout_id) from public.community_challenge_contributions where user_id=auth.uid() and(p_after is null or challenge_id::text||':'||day::text>p_after) order by challenge_id::text||':'||day::text limit p_limit;
 else return query select * from public.community_export_page_before_challenges(p_category,p_after,p_limit);end if;end $$;
do $$declare f record;begin for f in select p.oid::regprocedure sig,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and(p.proname like 'community_challenge%' or p.proname in('community_export_page','community_export_page_before_challenges'))loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);if f.proname in('community_challenges_rpc','community_export_page')then execute format('grant execute on function %s to authenticated',f.sig);end if;end loop;end $$;
alter function public.community_issue_report_receipt(text,text) rename to community_issue_report_receipt_before_challenges;
create function public.community_issue_report_receipt(p_target_type text,p_target_id text) returns table(id uuid) language plpgsql security definer set search_path='' as $$declare c public.community_challenges;snapshot jsonb;rid uuid;begin
 if p_target_type is distinct from 'challenge' then return query select * from public.community_issue_report_receipt_before_challenges(p_target_type,p_target_id);return;end if;
 perform public.community_lock();select * into c from public.community_challenges where community_challenges.id=p_target_id::uuid and user_id<>auth.uid() and public.community_challenge_access(community_challenges.id,auth.uid());
 if not found then raise exception 'community_unavailable';end if;
 snapshot:=jsonb_build_object('title',c.title,'startDay',c.start_day,'endDay',c.end_day);
 select receipt_row.id into rid from public.community_report_receipts receipt_row where receipt_row.user_id=auth.uid() and receipt_row.target_type='challenge' and receipt_row.target_id=c.id::text and receipt_row.subject_user_id=c.user_id and receipt_row.evidence_snapshot=snapshot and receipt_row.expires_at>now() order by receipt_row.created_at desc,receipt_row.id desc limit 1;
 if rid is null then insert into public.community_report_receipts(user_id,target_type,target_id,subject_user_id,evidence_snapshot) values(auth.uid(),'challenge',c.id::text,c.user_id,snapshot) returning community_report_receipts.id into rid;end if;
 if rid is null then raise exception 'community_rate_limited';end if;return query select rid;end $$;
-- The generic report insert below reuses durable verified receipts and the shared daily cap.
alter function public.community_submit_report(text,text,text,text,uuid) rename to community_submit_report_before_challenges;
create function public.community_submit_report(p_target_type text,p_target_id text,p_reason text,p_notes text default null,p_interaction_receipt_id uuid default null) returns setof public.community_reports language plpgsql security definer set search_path='' as $$declare r public.community_reports;receipt public.community_report_receipts;rid uuid;n integer;begin
 if p_target_type is distinct from 'challenge' then return query select * from public.community_submit_report_before_challenges(p_target_type,p_target_id,p_reason,p_notes,p_interaction_receipt_id);return;end if;
 perform public.community_lock();if auth.uid() is null or p_reason not in('harassment','offensive_content','impersonation','spam','unsafe_or_sexual_content','other') or p_reason is null or char_length(p_notes)>1000 then raise exception 'community_invalid_report';end if;
 rid:=p_interaction_receipt_id;if rid is null then select id into rid from public.community_report_receipts where user_id=auth.uid() and target_type=p_target_type and target_id=p_target_id and expires_at>now() order by created_at desc limit 1;end if;if rid is null then select id into rid from public.community_issue_report_receipt(p_target_type,p_target_id);end if;
 select * into receipt from public.community_report_receipts where id=rid and user_id=auth.uid() and target_type='challenge' and target_id=p_target_id and expires_at>now();if not found then raise exception 'community_unavailable';end if;
 select * into r from public.community_reports where reporter_user_id=auth.uid() and target_type=p_target_type and target_id=p_target_id and reason=p_reason and status in('submitted','under_review') order by created_at desc limit 1 for update;
 if found then update public.community_reports set notes=case when nullif(p_notes,'') is null then notes else left(concat_ws(E'\n',notes,p_notes),1000) end,updated_at=now() where id=r.id returning * into r;r.subject_user_id:=null;r.evidence_snapshot:='{}';r.assigned_to:=null;r.staff_notes:=null;return next r;return;end if;
 insert into public.community_report_usage(user_id,report_date,report_count) values(auth.uid(),(now() at time zone 'UTC')::date,1) on conflict(user_id,report_date) do update set report_count=community_report_usage.report_count+1 where community_report_usage.report_count<10 returning report_count into n;
 if n is null then raise exception 'community_rate_limited';end if;
 insert into public.community_reports(reporter_user_id,target_type,target_id,reason,notes,subject_user_id,evidence_snapshot,priority) values(auth.uid(),'challenge',p_target_id,p_reason,p_notes,receipt.subject_user_id,receipt.evidence_snapshot,case when p_reason in('harassment','unsafe_or_sexual_content') then 'urgent' else 'normal' end) returning * into r;
 r.subject_user_id:=null;r.evidence_snapshot:='{}';r.assigned_to:=null;r.staff_notes:=null;return next r;end $$;
alter function public.community_apply_moderation_action(uuid,text,text,text,integer) rename to community_apply_moderation_action_before_challenges;
create function public.community_apply_moderation_action(p_report_id uuid,p_decision text,p_decision_reason text,p_staff_notes text default null,p_suspension_duration_days integer default null) returns setof public.community_reports language plpgsql security definer set search_path='' as $$declare r public.community_reports;op uuid;begin
 select * into r from public.community_reports where id=p_report_id;
 if r.target_type<>'challenge' or p_decision<>'remove' then return query select * from public.community_apply_moderation_action_before_challenges(p_report_id,p_decision,p_decision_reason,p_staff_notes,p_suspension_duration_days);return;end if;
 op:=public.community_staff_required();perform public.community_lock();select * into r from public.community_reports where id=p_report_id for update;
 if r.status not in('submitted','under_review') or (r.assigned_to is not null and r.assigned_to<>op::text) or op=r.subject_user_id or op=r.reporter_user_id or nullif(btrim(p_decision_reason),'') is null or char_length(p_decision_reason)>500 or char_length(p_staff_notes)>1000 then raise exception 'community_conflict';end if;
 update public.community_challenges set canceled_at=coalesce(canceled_at,now()) where id::text=r.target_id and user_id=r.subject_user_id;
 insert into public.community_moderation_actions(report_id,target_type,target_id,action,reason,staff_operator,staff_notes) values(r.id,r.target_type,r.target_id,'remove',p_decision_reason,op,p_staff_notes);
 return query update public.community_reports set status='resolved',decision='remove',decision_reason=p_decision_reason,staff_notes=p_staff_notes,assigned_to=op::text,action_taken_at=now(),updated_at=now() where id=r.id returning *;end $$;
revoke all on function public.community_issue_report_receipt_before_challenges(text,text),public.community_submit_report_before_challenges(text,text,text,text,uuid),public.community_apply_moderation_action_before_challenges(uuid,text,text,text,integer),public.community_issue_report_receipt(text,text),public.community_submit_report(text,text,text,text,uuid),public.community_apply_moderation_action(uuid,text,text,text,integer) from public,anon,authenticated,service_role;
grant execute on function public.community_issue_report_receipt(text,text),public.community_submit_report(text,text,text,text,uuid),public.community_apply_moderation_action(uuid,text,text,text,integer) to authenticated;
commit;
